"use client";

import { BlockWithAlignableContents } from "@lexical/react/LexicalBlockWithAlignableContents";
import {
  DecoratorBlockNode,
  type SerializedDecoratorBlockNode,
} from "@lexical/react/LexicalDecoratorBlockNode";
import type {
  DOMConversionMap,
  DOMConversionOutput,
  DOMExportOutput,
  EditorConfig,
  ElementFormatType,
  LexicalEditor,
  LexicalNode,
  NodeKey,
  Spread,
} from "lexical";
import type { JSX } from "react";

type YouTubeComponentProps = Readonly<{
  className: Readonly<{
    base: string;
    focus: string;
  }>;
  format: ElementFormatType | null;
  nodeKey: NodeKey;
  videoId: string;
}>;

function YouTubeComponent({
  className,
  format,
  nodeKey,
  videoId,
}: YouTubeComponentProps) {
  return (
    <BlockWithAlignableContents
      className={className}
      format={format}
      nodeKey={nodeKey}
    >
      <iframe
        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
        allowFullScreen
        className="aspect-video h-auto w-full max-w-full rounded-xl border border-border/70 bg-muted shadow-xs md:w-[70%]"
        frameBorder="0"
        src={`https://www.youtube-nocookie.com/embed/${videoId}`}
        title="YouTube video"
      />
    </BlockWithAlignableContents>
  );
}

export type SerializedYouTubeNode = Spread<
  {
    videoId: string;
  },
  SerializedDecoratorBlockNode
>;

const convertYouTubeElement = (
  domNode: HTMLElement
): DOMConversionOutput | null => {
  const videoId = domNode.getAttribute("data-lexical-youtube");
  if (!videoId) {
    return null;
  }

  return {
    node: $createYouTubeNode(videoId),
  };
};

export class YouTubeNode extends DecoratorBlockNode {
  __videoId: string;

  static getType(): string {
    return "youtube";
  }

  static clone(node: YouTubeNode): YouTubeNode {
    return new YouTubeNode(node.__videoId, node.__format, node.__key);
  }

  static importJSON(serializedNode: SerializedYouTubeNode): YouTubeNode {
    return $createYouTubeNode(serializedNode.videoId).updateFromJSON(
      serializedNode
    );
  }

  static importDOM(): DOMConversionMap | null {
    return {
      iframe: (domNode: HTMLElement) => {
        if (!domNode.hasAttribute("data-lexical-youtube")) {
          return null;
        }

        return {
          conversion: convertYouTubeElement,
          priority: 1,
        };
      },
    };
  }

  constructor(videoId: string, format?: ElementFormatType, key?: NodeKey) {
    super(format, key);
    this.__videoId = videoId;
  }

  exportJSON(): SerializedYouTubeNode {
    return {
      ...super.exportJSON(),
      videoId: this.__videoId,
      type: "youtube",
      version: 1,
    };
  }

  exportDOM(): DOMExportOutput {
    const element = document.createElement("iframe");
    element.setAttribute("data-lexical-youtube", this.__videoId);
    element.setAttribute(
      "src",
      `https://www.youtube-nocookie.com/embed/${this.__videoId}`
    );
    element.setAttribute(
      "allow",
      "accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
    );
    element.setAttribute("allowfullscreen", "true");
    element.setAttribute("frameborder", "0");
    element.setAttribute("title", "YouTube video");
    return { element };
  }

  updateDOM(): false {
    return false;
  }

  getVideoId(): string {
    return this.getLatest().__videoId;
  }

  getTextContent(): string {
    return `https://www.youtube.com/watch?v=${this.__videoId}`;
  }

  decorate(_editor: LexicalEditor, config: EditorConfig): JSX.Element {
    const embedBlockTheme = config.theme.embedBlock ?? {};
    const className = {
      base: embedBlockTheme.base ?? "",
      focus: embedBlockTheme.focus ?? "",
    };

    return (
      <YouTubeComponent
        className={className}
        format={this.__format}
        nodeKey={this.getKey()}
        videoId={this.__videoId}
      />
    );
  }
}

export function $createYouTubeNode(videoId: string): YouTubeNode {
  return new YouTubeNode(videoId);
}

export function $isYouTubeNode(
  node: LexicalNode | null | undefined
): node is YouTubeNode {
  return node instanceof YouTubeNode;
}

import type { ElementTransformer } from "@lexical/markdown";
import { parseYouTubeUrl } from "../../../plugins/youtube/utils";
import { $createYouTubeNode, $isYouTubeNode, YouTubeNode } from "./node";

const YOUTUBE_URL_REGEXP = /^https?:\/\/\S+$/;

export const YOUTUBE_MARKDOWN_TRANSFORMER: ElementTransformer = {
  dependencies: [YouTubeNode],
  export: (node) => {
    if (!$isYouTubeNode(node)) {
      return null;
    }

    return `https://www.youtube.com/watch?v=${node.getVideoId()}`;
  },
  regExp: YOUTUBE_URL_REGEXP,
  replace: (parentNode, _children, match) => {
    const videoId = parseYouTubeUrl(match[0]);
    if (!videoId) {
      return;
    }

    parentNode.replace($createYouTubeNode(videoId));
  },
  type: "element",
};

import type { NodeKey } from "lexical";
import { createCommand } from "lexical";

export interface InsertYouTubePayload {
  /**
   * When omitted or empty the plugin opens its own insert dialog instead of
   * inserting directly — the slash menu and toolbars dispatch the bare
   * command without owning any dialog UI.
   */
  targetNodeKey?: NodeKey;
  videoId?: string;
}

export const INSERT_YOUTUBE_COMMAND = createCommand<InsertYouTubePayload>(
  "INSERT_YOUTUBE_COMMAND"
);

import { PlayIcon } from "lucide-react";
import { YouTubeNode } from "../../core/nodes/youtube/node";
import { YOUTUBE_MARKDOWN_TRANSFORMER } from "../../core/nodes/youtube/transformer";
import type { ExtraEditorFeature } from "../../core/types";
import { INSERT_YOUTUBE_COMMAND } from "./commands";
import { YouTubePlugin } from "./plugin";

/**
 * Installs the YouTube feature: the `YouTubeNode`, the URL markdown
 * transformer and the shared insert-menu entry. Ships as the `editor-youtube`
 * registry item.
 */
export const youtubeFeature: ExtraEditorFeature = {
  id: "youtube",
  nodes: [YouTubeNode],
  plugin: YouTubePlugin,
  slashCommands: [
    {
      command: {
        description: "Embed a YouTube video",
        icon: PlayIcon,
        id: "youtube",
        keywords: ["youtube", "video", "embed", "yt"],
        label: "YouTube",
      },
      run: (editor) => {
        editor.dispatchCommand(INSERT_YOUTUBE_COMMAND, {});
      },
    },
  ],
  transformers: [YOUTUBE_MARKDOWN_TRANSFORMER],
};

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { parseYouTubeUrl } from "../youtube/utils";

interface InsertYouTubeDialogProps {
  /** Prefix for form input ids so multiple mounted dialogs stay unique. */
  idPrefix?: string;
  onCancel: () => void;
  onSubmit: () => void;
  onUrlChange: (value: string) => void;
  open: boolean;
  youTubeUrl: string;
}

export function InsertYouTubeDialog({
  idPrefix = "slash",
  onCancel,
  onSubmit,
  onUrlChange,
  open,
  youTubeUrl,
}: InsertYouTubeDialogProps) {
  const handleOpenChange = (nextOpen: boolean) => {
    if (!nextOpen) {
      onCancel();
    }
  };

  return (
    <Dialog onOpenChange={handleOpenChange} open={open}>
      <DialogContent className="sm:max-w-lg" showCloseButton>
        <DialogHeader>
          <DialogTitle>Embed YouTube video</DialogTitle>
          <DialogDescription>
            Paste a YouTube URL and it will be embedded as a video block.
          </DialogDescription>
        </DialogHeader>

        <form
          className="space-y-4"
          onSubmit={(event) => {
            event.preventDefault();
            onSubmit();
          }}
        >
          <div className="grid gap-2">
            <label
              className="font-medium text-sm"
              htmlFor={`${idPrefix}-youtube-url`}
            >
              YouTube URL
            </label>
            <Input
              id={`${idPrefix}-youtube-url`}
              onChange={(event) => onUrlChange(event.target.value)}
              placeholder="https://www.youtube.com/watch?v=jNQXAC9IVRw"
              ref={(element) => {
                if (element && open) {
                  element.focus();
                }
              }}
              type="url"
              value={youTubeUrl}
            />
            <p className="text-muted-foreground text-xs">
              Supports `youtube.com`, `youtu.be`, and embed links.
            </p>
          </div>

          <DialogFooter showCloseButton={false}>
            <Button onClick={onCancel} type="button" variant="outline">
              Cancel
            </Button>
            <Button disabled={!parseYouTubeUrl(youTubeUrl)} type="submit">
              Embed video
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { $insertNodeToNearestRoot } from "@lexical/utils";
import {
  $createParagraphNode,
  $getNodeByKey,
  $getSelection,
  $isElementNode,
  $isRangeSelection,
  $isTextNode,
  COMMAND_PRIORITY_EDITOR,
  COMMAND_PRIORITY_HIGH,
} from "lexical";
import { useEffect, useState } from "react";
import { $createYouTubeNode, YouTubeNode } from "../../core/nodes/youtube/node";
import { INSERT_YOUTUBE_COMMAND } from "./commands";
import { InsertYouTubeDialog } from "./insert-dialog";

const insertParagraphAfterYouTube = (
  youTubeNode: ReturnType<typeof $createYouTubeNode>
) => {
  const paragraph = $createParagraphNode();
  youTubeNode.insertAfter(paragraph);
  paragraph.select();
};

const EMPTY_DIALOG_STATE = {
  open: false,
  pendingTargetKey: null as string | null,
  url: "",
};

export function YouTubePlugin() {
  const [editor] = useLexicalComposerContext();
  const [dialogState, setDialogState] = useState(EMPTY_DIALOG_STATE);

  useEffect(() => {
    if (!editor.hasNodes([YouTubeNode])) {
      throw new Error("YouTubePlugin: YouTubeNode not registered on editor");
    }

    return editor.registerCommand(
      INSERT_YOUTUBE_COMMAND,
      ({ targetNodeKey, videoId }) => {
        const trimmedVideoId = videoId?.trim();
        if (!trimmedVideoId) {
          return false;
        }

        const youTubeNode = $createYouTubeNode(trimmedVideoId);

        if (targetNodeKey) {
          const targetNode = $getNodeByKey(targetNodeKey);
          if (!$isElementNode(targetNode)) {
            return false;
          }

          targetNode.replace(youTubeNode);
          insertParagraphAfterYouTube(youTubeNode);
          return true;
        }

        $insertNodeToNearestRoot(youTubeNode);
        insertParagraphAfterYouTube(youTubeNode);
        return true;
      },
      COMMAND_PRIORITY_EDITOR
    );
  }, [editor]);

  // Incomplete payloads (no video id) mean "open the embed dialog".
  useEffect(() => {
    return editor.registerCommand(
      INSERT_YOUTUBE_COMMAND,
      (payload) => {
        if (payload.videoId?.trim()) {
          return false;
        }

        let targetNodeKey: string | null = payload.targetNodeKey ?? null;

        if (!targetNodeKey) {
          editor.getEditorState().read(() => {
            const selection = $getSelection();
            if (!$isRangeSelection(selection)) {
              return;
            }
            const node = selection.anchor.getNode();
            if ($isTextNode(node)) {
              targetNodeKey = node.getTopLevelElementOrThrow().getKey();
            }
          });
        }

        setDialogState({
          ...EMPTY_DIALOG_STATE,
          open: true,
          pendingTargetKey: targetNodeKey,
        });
        return true;
      },
      COMMAND_PRIORITY_HIGH
    );
  }, [editor]);

  const closeDialog = () => {
    setDialogState(EMPTY_DIALOG_STATE);
  };

  const handleSubmit = () => {
    editor.update(() => {
      editor.dispatchCommand(INSERT_YOUTUBE_COMMAND, {
        targetNodeKey: dialogState.pendingTargetKey ?? undefined,
        videoId: dialogState.url,
      });
    });
    closeDialog();
  };

  return (
    <InsertYouTubeDialog
      idPrefix="youtube-plugin"
      onCancel={closeDialog}
      onSubmit={handleSubmit}
      onUrlChange={(value) =>
        setDialogState((state) => ({ ...state, url: value }))
      }
      open={dialogState.open}
      youTubeUrl={dialogState.url}
    />
  );
}

const YOUTUBE_URL_PATTERN =
  /^.*(?:youtu\.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;

export const parseYouTubeUrl = (url: string): string | null => {
  const match = YOUTUBE_URL_PATTERN.exec(url.trim());
  const videoId = match?.[1];

  if (videoId?.length === 11) {
    return videoId;
  }

  return null;
};
